window.CONTRASTS_V2 = [{"module": 6, "title": "Whole report vs partial report", "a": {"term": "Whole report", "definition": "The person sees a flashed array of letters and then names as many as they can. In Sperling's (1960) display that was 12 letters in three rows of four."}, "b": {"term": "Partial report", "definition": "A tone played after the display disappears tells the person which one row to name. They cannot know in advance which row will be cued, so they cannot memorize just one."}, "diff": "Whole report averaged about 4.5 of 12 letters (about 37.5 percent), but partial report averaged about 3.3 of 4 letters (about 82 percent) whichever row was cued. Because people could report almost any row they were cued to, information about all the rows had to be available at the start. The whole-report limit is therefore a limit on how much can be reported before the trace fades, not on how much was perceived.", "example": "Sperling (1960) flashed three rows of four letters (X M L T, A F N B, C D Z P). People reported only a few when asked for everything, but nearly all of whichever row the tone picked out.", "watch": "The 82 percent is accuracy on the cued row. It does not mean people stored every letter perfectly. The tone only came after the display was gone, which is what shows all rows were available at first.", "score": 8.1, "tier": "mid", "basis": "2 matching Q&A questions, best 7.8"}, {"module": 6, "title": "Immediate vs delayed partial report", "a": {"term": "Immediate partial report", "definition": "The cue tone comes right as the display ends, so the person selects the cued row while the trace is still strong. Accuracy was about 3.3 of 4 letters (about 82 percent)."}, "b": {"term": "Delayed partial report", "definition": "The cue tone is held back by an extra delay before the person selects a row. Accuracy fell to about 1 of 4 letters (25 percent)."}, "diff": "The only thing that changes between the two is how long the person waits for the cue, so the drop shows the sensory trace is fading fast. As the cue is delayed, partial-report accuracy falls toward the whole-report level. Sensory memory therefore has a large capacity but a very short duration, with most information lost within about one second unless it is selected.", "example": "In Sperling (1960), the same cue that gave about 82 percent correct when immediate gave about 25 percent when it arrived after the delay.", "watch": "The fall does not mean the letters were never seen. It means the representation faded before the cue could be used to select from it.", "score": 8.1, "tier": "mid", "basis": "2 matching Q&A questions, best 7.8"}, {"module": 6, "title": "Sensory memory vs short-term memory", "a": {"term": "Sensory memory", "definition": "Briefly retains incoming stimulation for seconds or fractions of a second. It has a very large capacity but fades quickly unless attention selects part of it."}, "b": {"term": "Short-term memory", "definition": "Holds about five to seven items for roughly fifteen to twenty seconds. Rehearsal can keep the contents available and move them toward long-term memory."}, "diff": "The two stores of Atkinson and Shiffrin's (1968) modal model differ in how much they hold and how long it lasts. Sensory memory holds a lot for an instant, which is why Sperling's (1960) immediate cue let people report almost any row, and a delayed cue arrived after most of it had faded. Short-term memory holds a little for longer, and attention is what moves selected information from the first into the second.", "example": "Looking at a phone directory floods sensory memory with many items at once. Attention picks out the one number you want, which puts it in short-term memory, and repeating it keeps it there long enough to dial.", "watch": "Do not describe short-term memory as just a longer sensory memory. Sensory memory is large and fleeting, while short-term memory is small and depends on selection and rehearsal.", "score": 8.9, "tier": "mid", "basis": "4 matching Q&A questions, best 8.0"}, {"module": 6, "title": "Icon vs echo", "a": {"term": "Icon", "definition": "The fleeting visual trace left by stimulation. It is the visual form of sensory memory, and persistence of vision (a sparkler seeming to leave a trail) shows it."}, "b": {"term": "Echo", "definition": "The brief continuation of auditory information after a sound ends. It is the auditory form of sensory memory."}, "diff": "Both are sensory memory and both fade within seconds or fractions of a second, so the only difference is the sense involved: seeing for the icon and hearing for the echo. Neither is the durable representation used to remember something much later.", "example": "Sperling (1960) studied iconic memory with flashed letters. As an illustration of an echo, you can still replay the last few words someone said for a moment after they stop.", "watch": "A large capacity does not mean a long duration. Both traces decay quickly.", "score": 3.6, "tier": "low", "basis": "1 matching Q&A question, best 3.6"}, {"module": 6, "title": "Decay vs interference", "a": {"term": "Decay", "definition": "A memory trace weakens simply because time passes. It predicts the same loss at the same delay on every trial."}, "b": {"term": "Interference", "definition": "Other memories compete with the one being tested. It predicts that loss depends on how much competing material there is, not only on time."}, "diff": "In Brown (1958) and Peterson and Peterson (1959), participants saw three letters and a number and counted backward by threes for 3 to 18 seconds, which blocks rehearsal. The average over all trials fell steadily, and Peterson and Peterson read that as decay. But at 18 seconds recall was relatively high on trial 1, lower by trial 3, and very low after many trials, so the same delay did far more damage when more earlier sets had piled up. As presented, that trial-by-trial pattern points to proactive interference, which Keppel and Underwood (1962) offered as the alternative account.", "example": "The same 18-second delay gave high recall on the first trial and very low recall after many trials.", "watch": "If an answer says forgetting happened 'because of time' but ignores the trial history, it is describing decay when the pattern shows interference.", "score": 10.4, "tier": "high", "basis": "4 matching Q&A questions, best 9.5"}, {"module": 6, "title": "Retroactive vs proactive interference", "a": {"term": "Retroactive interference", "definition": "New information disrupts memory for older information. The memory that suffers is the old one, and the competitor arrived later."}, "b": {"term": "Proactive interference", "definition": "Old information disrupts memory for newer information. The memory that suffers is the new one, and the competitor arrived earlier."}, "diff": "To label it correctly, first decide which information the person is trying to recall, then ask whether the competing information came before or after it. Earlier competing material is proactive and later competing material is retroactive. Routine events are especially vulnerable because similar memories compete, and both kinds are reduced when events are distinctive.", "example": "Learning a new phone number and then struggling to recall the old one is retroactive. Previous parking spots making today's spot hard to remember is proactive, and so are earlier trigrams harming recall of the current one in Brown (1958) and Peterson and Peterson (1959).", "watch": "Do not pick by which memory is 'newer' in general. The question is always about the direction of harm relative to the item being recalled.", "score": 3.8, "tier": "low", "basis": "1 matching Q&A question, best 3.8"}, {"module": 6, "title": "Average over all trials vs trial-by-trial recall", "a": {"term": "Average over all trials", "definition": "Pools every trial together, so recall appears to drop steadily as the delay grows from 3 to 18 seconds, as though short-term memory simply decays."}, "b": {"term": "Trial-by-trial recall", "definition": "Looks at early and late trials separately. Early trials keep high recall even at 18 seconds, and later trials show very low recall at the same delay."}, "diff": "The steep drop in the average comes mostly from the later trials, where proactive interference has built up. Averaging hides the interference behind something that looks like decay. This is why the Brown-Peterson pattern is evidence for interference and not only for time-based decay.", "example": "In Brown (1958) and Peterson and Peterson (1959), recall at 18 seconds was relatively high on trial one, lower by trial three, and substantially reduced after many trials.", "watch": "The average blends early trials with high recall and late trials with very low recall, so it hides where the steep drop actually comes from.", "score": 8.1, "tier": "mid", "basis": "3 matching Q&A questions, best 7.5"}, {"module": 6, "title": "Maintenance rehearsal vs elaborative rehearsal", "a": {"term": "Maintenance rehearsal", "definition": "Repeating information, such as silently saying a label or number, to prolong how long it stays available in short-term memory."}, "b": {"term": "Elaborative rehearsal", "definition": "Linking new information to knowledge already in long-term memory, such as explaining how it relates to what you know."}, "diff": "Maintenance keeps information alive only while the repeating continues. Elaborative rehearsal adds meaning, which supports learning that lasts longer. Recoding is a third control process: it reorganizes or modifies information that is already in short-term memory.", "example": "Repeating a label over and over keeps it available (maintenance). Explaining how the label relates to something you already know supports longer-term learning (elaborative).", "watch": "Repetition is not the same as understanding. If the question stresses meaning or links to existing knowledge, the answer is elaborative.", "score": 4.5, "tier": "low", "basis": "1 matching Q&A question, best 4.5"}, {"module": 6, "title": "Miller's seven plus or minus two vs three to four items", "a": {"term": "Seven plus or minus two units", "definition": "Miller's (1956) estimate of short-term capacity, where a unit can be a digit, word, number or phrase and differs across tasks."}, "b": {"term": "About three to four items", "definition": "Alvarez and Cavanagh's (2004) estimate for visual short-term memory from change detection, where accuracy falls sharply above roughly four items."}, "diff": "Miller's units can hold different amounts of information, so the title does not prove that every system holds exactly seven raw items. The figures come from different places: five to seven is the modal-model estimate for short-term memory, seven plus or minus two is Miller's, and three to four is Alvarez and Cavanagh's (2004) estimate for visual objects, where colored squares gave a higher estimated capacity than complex polygons or shaded cubes. Different tasks need not measure one identical capacity.", "example": "In Alvarez and Cavanagh (2004), the first array stayed up for 100 milliseconds, the second for 2,000 milliseconds, and people judged whether the two matched.", "watch": "Do not treat seven as a universal limit for visual memory. The amount of information in each object matters.", "score": 8.8, "tier": "mid", "basis": "2 matching Q&A questions, best 8.5"}, {"module": 6, "title": "Single item vs chunk", "a": {"term": "Item", "definition": "One basic unit, such as a single digit, letter or word."}, "b": {"term": "Chunk", "definition": "A larger meaningful unit built from smaller ones, such as a familiar group of digits."}, "diff": "Chunking raises effective capacity by letting each slot in short-term memory carry more information, so the same limited number of units holds more. The gain comes from knowledge-based organization, not from enlarging every raw limit equally.", "example": "Ericsson and colleagues (1980) trained a student to reach a digit span of 79 by treating strings of digits as familiar running times, so each running time was one chunk.", "watch": "A big span after training does not mean the memory system itself got bigger. It means each unit holds more.", "score": 10.0, "tier": "high", "basis": "2 matching Q&A questions, best 9.7"}, {"module": 6, "title": "Episodic vs semantic memory", "a": {"term": "Episodic memory", "definition": "Memory for personal events tied to a particular time and place. Tulving described it as a kind of mental time travel."}, "b": {"term": "Semantic memory", "definition": "Memory for facts and general knowledge that is not tied to the moment you learned it."}, "diff": "Both are branches of declarative memory inside long-term memory, and the other major branch of long-term memory is procedural memory, which concerns skills. Episodic memory answers 'what happened to me then', and semantic memory answers 'what do I know'. They are classified by function, not by how long they last.", "example": "As an illustration, remembering one particular birthday party is episodic, and knowing what a birthday is is semantic.", "watch": "Neither is an extra short-term store. They sit in long-term memory.", "score": 4.8, "tier": "low", "basis": "2 matching Q&A questions, best 4.5"}, {"module": 6, "title": "Duration vs capacity", "a": {"term": "Duration", "definition": "How long information stays available in short-term memory, roughly fifteen to twenty seconds without rehearsal."}, "b": {"term": "Capacity", "definition": "How much information can be held at once, traditionally about seven plus or minus two units."}, "diff": "Duration is how long information stays available, and capacity is how much can be held at once. Each can be changed by a strategy: rehearsal prolongs duration, and chunking raises effective capacity. So when a result changes, ask which strategy was used and not only which memory system is involved.", "example": "Counting backward blocks rehearsal in Brown (1958) and Peterson and Peterson (1959), so a trigram is lost within about fifteen to twenty seconds. Ericsson and colleagues (1980) raised a digit span to 79 by chunking.", "watch": "A question about 'how long' is duration and 'how much' is capacity. Mixing them up is a common slip.", "score": 8.7, "tier": "mid", "basis": "4 matching Q&A questions, best 7.8"}, {"module": 9, "title": "Short-term memory vs working memory", "a": {"term": "Short-term memory (Atkinson and Shiffrin, 1968)", "definition": "A single component that holds what has been selected for a short time. Rehearsal keeps its contents available, and the emphasis is on temporary availability."}, "b": {"term": "Working memory (Baddeley and Hitch, 1974)", "definition": "A limited-capacity system for the temporary storage and manipulation of information, with a central executive, a phonological loop and a visuospatial sketchpad."}, "diff": "The working-memory model treats memory as active: information is held and worked on at the same time. It also separates verbal and auditory information from visual and spatial information, with the central executive coordinating them. Baddeley added the episodic buffer in 2000, so it belongs to the expanded model.", "example": "In 43 × 6, the 8 from 3 × 6 = 18 is held (storage) while the 1 is carried and 6 × 4 = 24 is computed (an operation). The 8 has to survive while other steps run.", "watch": "Do not describe working memory as passive storage. Comprehension, learning and reasoning need holding and operating together.", "score": 7.8, "tier": "mid", "basis": "3 matching Q&A questions, best 7.2"}, {"module": 9, "title": "Phonological loop vs visuospatial sketchpad", "a": {"term": "Phonological loop", "definition": "Maintains verbal and auditory information, with a phonological store that holds it and an articulatory rehearsal process that repeats the sounds, even silently."}, "b": {"term": "Visuospatial sketchpad", "definition": "Holds visual information (what something looks like) and spatial information (where its parts are and how they are arranged)."}, "diff": "Ask whether the content is sounds and words or shapes and locations. Brooks's (1968) opposite results show the two are at least partly independent. Both interact with long-term knowledge, so one calculation can use verbal rehearsal of a result together with a picture of the digits.", "example": "A remembered sentence uses the loop. The remembered shape of an F uses the sketchpad.", "watch": "The central executive is not a store for any particular kind of content. It directs and coordinates the other two.", "score": 10.7, "tier": "high", "basis": "5 matching Q&A questions, best 9.5"}, {"module": 9, "title": "Brooks's sentence task vs F task", "a": {"term": "Sentence task (Brooks, 1968)", "definition": "People memorized a sentence and decided for each word whether it was a noun, responding by speaking or by pointing. Pointing was easier."}, "b": {"term": "F task (Brooks, 1968)", "definition": "People memorized the shape of an F and classified each corner as inside or outside, responding by speaking or by pointing. Speaking was easier."}, "diff": "In the sentence task, holding the sentence used the phonological loop, so speaking the answers competed with it. In the F task, following the F used the sketchpad, so pointing to spatially arranged responses competed with it. A task is easier when the information held and the operation performed use different types of short-term memory.", "example": "Holding a sentence while speaking answers interfered in the sentence task, and holding an F while pointing to answers interfered in the F task.", "watch": "Memorize the logic, not just the result: the easier response is the one that uses the other system.", "score": 9.8, "tier": "high", "basis": "2 matching Q&A questions, best 9.5"}, {"module": 9, "title": "Phonological store vs articulatory rehearsal", "a": {"term": "Phonological store", "definition": "The part of the phonological loop that holds verbal and auditory information for a short time."}, "b": {"term": "Articulatory rehearsal process", "definition": "The part that keeps the contents active by repeating the sounds, even silently."}, "diff": "Articulatory suppression, speaking while trying to memorize, occupies the rehearsal process. That reduces recall, and it reduces both the word-length effect (because short words no longer win by being quicker to rehearse) and the phonological similarity effect (because converting seen items into sounds is disrupted).", "example": "As an illustration, repeating an unrelated word while trying to memorize a list leaves the rehearsal process busy.", "watch": "Suppression does not erase the store. It blocks the process that refreshes it.", "score": 7.0, "tier": "low", "basis": "3 matching Q&A questions, best 6.4"}, {"module": 9, "title": "Word-length effect vs phonological similarity effect", "a": {"term": "Word-length effect", "definition": "Lists of short words are remembered better than lists of long words, because longer words take more time to say and rehearse."}, "b": {"term": "Phonological similarity effect", "definition": "Items that sound alike are confused with each other, even when they look different."}, "diff": "Word length is about the time needed to rehearse the items, and similarity is about overlapping sound codes. Both support the idea that verbal maintenance depends on sound-based codes and speech-related rehearsal, and articulatory suppression reduces both.", "example": "Word length: Baddeley and colleagues (1975, 1984) found more short words were recalled than long words, and Ellis and Hennelly (1980) found Welsh-English bilingual children had a shorter digit span in Welsh because Welsh number names take longer to say. Phonological similarity: E is confused with B because they sound alike.", "watch": "Span tracks how much can be said in about 1.5 to 2 seconds, so the language difference follows the time to say the number names and not the numbers themselves.", "score": 10.1, "tier": "high", "basis": "3 matching Q&A questions, best 9.5"}, {"module": 9, "title": "Central executive vs the two storage systems", "a": {"term": "Central executive", "definition": "Directs and maintains attention, divides attention, switches it when the task changes, suppresses irrelevant information, coordinates the other components and performs calculations."}, "b": {"term": "Phonological loop and sketchpad", "definition": "Hold and rehearse particular kinds of content: verbal and auditory for the loop, visual and spatial for the sketchpad."}, "diff": "The executive is about control, and the other two are about content. Naming a controller does not explain how control is done, which is why the executive is criticized as a homunculus, and it is today often split into updating, shifting and inhibition (Miyake and colleagues, 2000).", "example": "As an illustration, following a phone number while giving directions needs the executive to split attention while the loop rehearses the digits.", "watch": "Do not describe the executive as storing information.", "score": 9.4, "tier": "high", "basis": "5 matching Q&A questions, best 8.2"}, {"module": 9, "title": "Updating vs shifting", "a": {"term": "Updating", "definition": "Changing the information currently being maintained as new information arrives."}, "b": {"term": "Shifting", "definition": "Changing the task or operation being performed."}, "diff": "Miyake and colleagues (2000) separate these two from inhibition, which suppresses information or responses that interfere with the goal. Updating is about the contents of memory, shifting is about the operation, and inhibition is about what to block.", "example": "As an illustration, replacing the contents you are holding with new ones is updating, switching from adding to multiplying is shifting, and ignoring a distracting number is inhibition.", "watch": "All three are functions inside what would otherwise be one broad label, the executive.", "score": 6.6, "tier": "low", "basis": "1 matching Q&A question, best 6.6"}, {"module": 9, "title": "Original three-part model vs the episodic buffer", "a": {"term": "Original model", "definition": "The central executive, phonological loop and visuospatial sketchpad proposed by Baddeley and Hitch (1974)."}, "b": {"term": "Episodic buffer (Baddeley, 2000)", "definition": "A fourth component of limited capacity, about four chunks, that binds information from the loop, the sketchpad and long-term memory into integrated episodes."}, "diff": "The buffer is needed because people can immediately recall about 16 words from a meaningful sentence, more than their span for unrelated words, since meaning and long-term language knowledge let the words stay connected. Some amnesic patients can immediately recall a just-heard story, which suggests immediate retention of an organized episode can survive when longer-term memory is impaired.", "example": "A sentence's words are kept together as connected material, not as 16 separate items.", "watch": "The buffer is not part of the original three-component proposal.", "score": 7.5, "tier": "mid", "basis": "2 matching Q&A questions, best 7.2"}, {"module": 9, "title": "High-capacity vs low-capacity participants", "a": {"term": "High-capacity participants", "definition": "Kept irrelevant blue bars out of working memory, so adding two blue distractors to two red targets changed their response little."}, "b": {"term": "Low-capacity participants", "definition": "Let the irrelevant bars in, so the same distractors raised their response toward the four-item level."}, "diff": "Vogel and colleagues (2005) recorded event-related potentials during a task where red bars were shown for 100 milliseconds and held across a 900 millisecond retention interval. Capacity was positively correlated with filtering efficiency, so people with higher capacity are also less distracted, and a lower score can reflect competing material occupying processing the targets needed.", "example": "Two red targets alone against two red plus two blue: the ERP response barely changed for high-capacity people and rose for low-capacity people.", "watch": "Capacity here is not only about holding items. It is also about keeping the wrong ones out.", "score": 8.0, "tier": "mid", "basis": "2 matching Q&A questions, best 7.7"}, {"module": 9, "title": "Rotating a representation vs storing a fixed picture", "a": {"term": "Storing an unchanged picture", "definition": "Holding the image as it was seen, with no operation applied. If this were all that happened, deciding whether two views match would take about the same time whatever the angle between them."}, "b": {"term": "Mental rotation", "definition": "Turning an internal representation to line it up with the other view, in the picture plane or in depth. A bigger angle needs more turning, so it takes longer."}, "diff": "Shepard and Metzler (1971) showed pairs of block-built objects at different orientations and asked whether they matched. For picture-plane pairs, reaction time rose approximately linearly with the angle, so small angles were answered faster than large ones. A static copy would predict no angle effect, so the pattern points to an active operation on a spatial representation.", "example": "People judged whether pairs of block-built objects matched, and small angles were answered faster than large ones.", "watch": "The evidence is the shape of the reaction-time curve and not what people say they felt, and the linear pattern was for picture-plane pairs.", "score": 9.5, "tier": "high", "basis": "1 matching Q&A question, best 9.5"}, {"module": 10, "title": "States vs operators", "a": {"term": "States", "definition": "The initial state, the intermediate states along the way, and the goal state of a problem."}, "b": {"term": "Operators", "definition": "The rules that say which moves are allowed. Applying one changes the problem from one state to another."}, "diff": "The problem space is the set of states, and operators are what connect them. Knowing the initial and goal states does not tell you which intermediate states link them, so solving means finding a sequence of operator applications that reaches the goal.", "example": "In the Tower of Hanoi the starting stack is the initial state and the completed stack on the target peg is the goal. The operators are one disk at a time, only a disk with nothing on top, and never a larger disk on a smaller one.", "watch": "Stating the goal exactly does not solve the problem. In the numbered-tile puzzle you can describe the finished board and still not know the moves.", "score": 8.5, "tier": "mid", "basis": "3 matching Q&A questions, best 7.9"}, {"module": 10, "title": "Problem solving as search vs as restructuring", "a": {"term": "Search (Newell and Simon, 1956)", "definition": "Problem solving as the activity between posing a problem and reaching its solution, finding a route through possible states. Means-end analysis reduces the difference between the current state and the goal."}, "b": {"term": "Restructuring (Gestalt, Koffka, 1935)", "definition": "A perceptual view in which the way the problem is organized in the mind affects which solution is available. Restructuring reorganizes the representation so a hidden relationship becomes usable."}, "diff": "Search is about moving through states step by step. Restructuring is about changing the representation so the answer appears. Some problems are solved by successive operations, and others by a sudden reorganization.", "example": "In Köhler's circle problem, the black line is one diagonal of a rectangle whose other diagonal is a radius, and the two diagonals of a rectangle are equal, so x = r.", "watch": "Newell and Simon developed the Logic Theorist for the search view. Do not attribute restructuring to them.", "score": 10.2, "tier": "high", "basis": "3 matching Q&A questions, best 9.6"}, {"module": 10, "title": "Insight vs noninsight problems", "a": {"term": "Insight problem", "definition": "Solved by a sudden realization after the representation changes, as in the triangle and chain problems."}, "b": {"term": "Noninsight problem", "definition": "Solved by successive operations that bring the solver closer, as in algebra."}, "diff": "Metcalfe and Wiebe (1987) had people rate warmth every 15 seconds. For algebra, warmth rose gradually as the solution approached. For insight problems it stayed low until close to the solution and then jumped sharply, from about 3 to 7. People cannot anticipate how near they are on insight problems.", "example": "In Metcalfe and Wiebe (1987), triangle and chain problems were compared with algebra.", "watch": "Not every problem is solved with an Aha experience. Some allow a methodical route.", "score": 9.5, "tier": "high", "basis": "1 matching Q&A question, best 9.5"}, {"module": 10, "title": "Functional fixedness vs mental set", "a": {"term": "Functional fixedness", "definition": "Restricting an object to its familiar function."}, "b": {"term": "Mental set", "definition": "A preconceived notion about how to approach a problem, based on past experience with that problem or similar ones."}, "diff": "Fixedness is about an object's use, and a set is about a method of solving. Both are forms of fixation, which Gestalt psychologists saw as a major obstacle.", "example": "Seeing the matchbox only as a container blocks the candle solution. In the water-jug problems the familiar B − A − 2C procedure blocks the simpler A + C and A − C.", "watch": "Ask whether the block is about what an object is for or about which procedure keeps being applied.", "score": 6.8, "tier": "low", "basis": "2 matching Q&A questions, best 6.5"}, {"module": 10, "title": "Candle problem vs two-string problem", "a": {"term": "Candle problem", "definition": "Mount a candle on a corkboard so wax does not drip. The solution is to tack the matchbox to the board as a platform. Participants given empty matchboxes were twice as likely to solve it."}, "b": {"term": "Two-string problem", "definition": "Tie together two strings hanging too far apart to reach both. The solution is to tie pliers to one string as a pendulum weight. When an experimenter accidentally set a string in motion, most participants solved it."}, "diff": "Both are functional fixedness. In the candle problem the box is seen as a container and not a platform. In the two-string problem the pliers are seen as a gripping tool and not a weight. In the two-string problem a hint that restructured the representation made the string something that could swing within reach.", "example": "The objects and the requirements stay the same, but the solver uses a different relationship among them.", "watch": "Both solutions require a new use for a familiar object.", "score": 6.5, "tier": "low", "basis": "1 matching Q&A question, best 6.5"}, {"module": 10, "title": "Blank board vs bread-and-butter board", "a": {"term": "Blank or colored board", "definition": "The squares are unlabeled or only colored, so nothing points the solver toward the pairing a domino needs."}, "b": {"term": "Bread-and-butter board", "definition": "The squares are labeled bread and butter, which emphasizes the difference between the two kinds of square and the pairing a domino needs."}, "diff": "How a problem is stated changes its difficulty. The labels made it easier to represent a domino as needing one of each kind. Participants in the bread-and-butter condition solved the problem twice as fast as those with the blank board.", "example": "With a think-aloud protocol, solvers in the bread-and-butter condition shift from treating squares as positions to considering the relationship between the two kinds of square.", "watch": "The objects and the requirement did not change. Only the representation did.", "score": 8.5, "tier": "mid", "basis": "6 matching Q&A questions, best 7.0"}, {"module": 10, "title": "Total area vs pairing (mutilated checkerboard)", "a": {"term": "Total area reasoning", "definition": "62 squares matches the area of 31 dominoes, so it seems the board can be covered."}, "b": {"term": "Pairing reasoning", "definition": "Every domino covers one square of each color, and the two removed corners are the same color, so the colors are unequal."}, "diff": "Equal total area does not guarantee a legal arrangement. The color imbalance applies to every possible placement, so the covering is impossible. Reasoning in terms of pairs exposes a constraint area alone hides.", "example": "An ordinary board has 64 squares and 32 dominoes cover it. Remove two opposite corners and 62 squares remain, but they are 30 of one color and 32 of the other, while 31 dominoes would need 31 of each.", "watch": "Moving the dominoes around cannot change the imbalance.", "score": 7.6, "tier": "mid", "basis": "4 matching Q&A questions, best 6.7"}, {"module": 10, "title": "Goal vs subgoal", "a": {"term": "Goal", "definition": "The condition you are trying to reach, such as the whole stack moved to the third peg."}, "b": {"term": "Subgoal", "definition": "A condition that makes part of the larger task possible, not the final answer."}, "diff": "Means-end analysis organizes search around reducing the difference between the current situation and the goal, and subgoals are the steps that do it. Different subgoals address different obstacles to the same move, one at the source and one at the destination.", "example": "In the Tower of Hanoi, the first subgoal is freeing the large disk. The second is freeing the third peg. The third is moving the large disk.", "watch": "A subgoal is not the final answer, and the smaller disks still have to be brought over afterward.", "score": 6.6, "tier": "low", "basis": "1 matching Q&A question, best 6.6"}, {"module": 11, "title": "Surface features vs structural features", "a": {"term": "Surface features", "definition": "The specific elements used to describe a problem, such as a fortress, a tumor, a lightbulb, a laser or a ray."}, "b": {"term": "Structural features", "definition": "The underlying principle that governs the solution, such as a strong force that would damage the surroundings if sent through one path."}, "diff": "Surface features are what the objects are, and structural features are why a solution works. Similar surface features can help a person notice a possible link, but transfer depends on matching structure. Two lightbulb versions can keep the same surface features while changing the structure.", "example": "In the radiation and fragile-glass problems a strong ray would damage the surroundings on its way to an internal target, so several low-intensity beams must converge.", "watch": "A fortress and a tumor do not look alike, yet they share the structure.", "score": 10.1, "tier": "high", "basis": "4 matching Q&A questions, best 9.2"}, {"module": 11, "title": "Noticing vs mapping vs applying", "a": {"term": "Noticing", "definition": "Recognizing that a source problem may be relevant to the target. It is crucial and can be the hardest step."}, "b": {"term": "Mapping and applying", "definition": "Linking the elements and relationships of the source to the target, then using that link to generate a parallel solution."}, "diff": "Gick and Holyoak distinguished these steps. After reading the fortress story only about 30 percent of participants solved the radiation problem, and when told to think about the story success rose to about 75 percent. Having the source in memory did not guarantee spontaneous use, which points to noticing as a major bottleneck.", "example": "In the Russian marriage problem mapped to the checkerboard, marriages correspond to dominoes and the two groups of people to the two square colors.", "watch": "Do not describe noticing as the same thing as mapping. Noticing is finding the source.", "score": 7.6, "tier": "mid", "basis": "1 matching Q&A question, best 7.6"}, {"module": 11, "title": "Source problem vs target problem", "a": {"term": "Source problem", "definition": "A problem with relevant similarities whose solution guides a new problem."}, "b": {"term": "Target problem", "definition": "The problem currently being solved."}, "diff": "Analogical problem solving transfers a solution from the source to the target. The useful information is the relationship among the elements, not their identical appearance.", "example": "The Russian marriage problem is the source and the mutilated checkerboard is the target. Duncker's radiation problem is the source for the lightbulb problem.", "watch": "The target is what you need to solve now. The source is what you already know.", "score": 6.7, "tier": "low", "basis": "1 matching Q&A question, best 6.7"}, {"module": 11, "title": "Spontaneous vs prompted use of an analogy", "a": {"term": "Spontaneous use", "definition": "A source in memory is used without a hint. After just reading the fortress story, about 30 percent of participants solved the radiation problem."}, "b": {"term": "Prompted use", "definition": "The person is told to think about the story they read. Then about 75 percent solved the radiation problem."}, "diff": "The people and the story in memory were the same, and only the hint differed. So having the source available was not enough: the reminder made the relevant source available for mapping and application, and noticing is a major bottleneck. Only about 10 percent reach the solution without a helpful analogy.", "example": "Gick and Holyoak's fortress story: a rebel general sends small groups along different roads so mines do not explode, and they arrive together to attack.", "watch": "Having a source in memory is not the same as using it.", "score": 7.6, "tier": "mid", "basis": "1 matching Q&A question, best 7.6"}, {"module": 11, "title": "Fragile-glass vs insufficient-intensity lightbulb sources", "a": {"term": "Fragile-glass source", "definition": "A high-intensity beam would break the glass, which matches the healthy-tissue constraint. About 69 percent who read it solved the radiation problem."}, "b": {"term": "Insufficient-intensity source", "definition": "The laser can only make low-intensity beams that cannot fuse the filament, so beams are combined, but there is no surrounding-damage constraint. About 33 percent solved it."}, "diff": "Both use converging beams, so the surface story is similar, but the structural constraint differs. The transfer rates follow how well the underlying constraint matches the target.", "example": "About 69 percent who read the fragile-glass version solved the radiation problem, against about 33 percent who read the insufficient-intensity version.", "watch": "Both are lightbulb sources. The difference is the surrounding-damage constraint.", "score": 7.4, "tier": "mid", "basis": "1 matching Q&A question, best 7.4"}, {"module": 11, "title": "Lightbulb with vs without the radiation source", "a": {"term": "With the radiation problem as a source", "definition": "The tumor and the filament are both targets needing a strong local effect, and healthy tissue and fragile glass are both surroundings that a single strong approach would damage. About 81 percent solved the lightbulb problem."}, "b": {"term": "Without the source (control)", "definition": "About 10 percent solved the lightbulb problem."}, "diff": "The radiation problem works as a source because it shares the structure, and the surface features also overlap, since both direct a beam toward an internal target, which makes the link easier to notice.", "example": "Ruth's sealed lightbulb has a broken filament, and several low-intensity lasers from different directions fuse it without breaking the glass.", "watch": "The solution is several weak beams converging, not one strong beam.", "score": 6.8, "tier": "low", "basis": "1 matching Q&A question, best 6.8"}, {"module": 11, "title": "Experts vs novices organizing problems", "a": {"term": "Experts", "definition": "Physics professors who sorted problems by structural features, such as conservation of energy."}, "b": {"term": "Novices", "definition": "Students with one semester of physics who sorted problems by surface features, such as inclined planes."}, "diff": "In Chi et al. (1982) the same problem 24 got a different partner under the two organizations. Novices paired 23 and 24 because both have inclines, and experts paired 21 and 24 through conservation of energy even though 21 has a block and spring on a horizontal surface. Expertise changes which relationship is the basis for similarity.", "example": "Chi et al. (1982) had physics professors and students sort 24 physics problems into groups by similarity.", "watch": "Novices go by what the problem looks like. Experts go by the principle that solves it.", "score": 9.5, "tier": "high", "basis": "2 matching Q&A questions, best 9.2"}, {"module": 11, "title": "Meaningful vs random chess positions", "a": {"term": "Actual game positions", "definition": "A master sees familiar groups of pieces and recalls each group as one chunk drawn from long-term memory."}, "b": {"term": "Random arrangements", "definition": "The same kinds of pieces on the same board with no meaningful relationships, so there are no familiar chunks and the master must remember piece by piece."}, "diff": "Chase and Simon (1973) compared a chess master with a beginner who had fewer than 100 hours of experience, giving each five seconds with the board. The master was much better on real positions and the advantage was greatly reduced on random ones, so the edge comes from organized domain knowledge and not a general memory advantage.", "example": "The pieces were of the same kinds in both conditions, and only the meaning of the arrangement changed.", "watch": "A chess master does not have a better memory in general.", "score": 10.1, "tier": "high", "basis": "2 matching Q&A questions, best 9.8"}, {"module": 11, "title": "Comparing sources vs using one source", "a": {"term": "Using one source", "definition": "Applying a single familiar story or problem to a new target, so what you notice depends on how much the target looks like that source."}, "b": {"term": "Analogical encoding", "definition": "Comparing two sources and working out what they share, for example two stories in which separate weak forces converge on one target."}, "diff": "With one source, the structure is buried in that story's details. With two sources the details do not match, so what is left in common is the structure, which directs reasoning toward structural features. A later target can then be approached through the common relationship and not through one familiar situation.", "example": "Compare the fortress story with a second convergence story, then try the radiation problem.", "watch": "Analogical encoding is about comparing sources, not about being reminded of one.", "score": 6.4, "tier": "low", "basis": "1 matching Q&A question, best 6.4"}, {"module": 11, "title": "Laboratory analogies vs in vivo analogies", "a": {"term": "Laboratory tasks", "definition": "Researchers give a source and a target under controlled conditions, and people often fail to use the analogy on their own, as when the fortress story helped only about 30 percent."}, "b": {"term": "In vivo problem solving", "definition": "Researchers observe people solving real problems in their ordinary setting, where analogies are used routinely."}, "diff": "This is the analogical paradox: analogies are hard to use in the laboratory and routine in real work. In vivo research keeps the ordinary context but is time-consuming and gives up control of variables, while laboratory work isolates variables but removes the context.", "example": "Fortress to radiation gave about 30 percent unprompted, while scientists use about 3 to 15 analogies in a one-hour laboratory meeting.", "watch": "The paradox is a contrast in how often analogies are used, not a contradiction in the theory.", "score": 6.4, "tier": "low", "basis": "1 matching Q&A question, best 6.4"}, {"module": 11, "title": "Expert strengths vs expert limits", "a": {"term": "Within the field", "definition": "An expert is extremely knowledgeable after a very long time learning and practicing, perhaps 10,000 to 20,000 hours for chess. Experts solve problems in their field faster and more successfully than beginners and spend more time analyzing before proceeding."}, "b": {"term": "Outside the field and in new situations", "definition": "The advantage is specific to the field, so experts are no better than novices outside it. Too much knowledge can lock in a familiar approach and make the expert less open to new ways of looking at a problem."}, "diff": "The same knowledge causes both. It lets experts recognize the principle behind a problem, as in Chi et al. (1982), but when a problem needs the usual procedure dropped, the knowledge can act like a mental set.", "example": "Physics professors in Chi et al. (1982) sorted problems by principle, which is a strength. A familiar procedure dominating, as in the water-jug problems, shows the limit.", "watch": "Expert does not mean better at everything.", "score": 4.4, "tier": "low", "basis": "1 matching Q&A question, best 4.4"}, {"module": 12, "title": "Availability vs representativeness heuristic", "a": {"term": "Availability heuristic", "definition": "Judging how likely something is by how easily examples come to mind."}, "b": {"term": "Representativeness heuristic", "definition": "Judging whether A belongs to class B by how much A resembles B."}, "diff": "Ask what supplies the shortcut. Remembered examples mean availability, and similarity to a type means representativeness. Heuristics are rapid rules of thumb that are likely to give a correct answer but are not foolproof.", "example": "A botulism death in the news makes it seem likelier than asthma (availability). Robert resembling a librarian makes people say librarian (representativeness).", "watch": "Memorability is also affected by distinctiveness and emotion, which do not make an event more common.", "score": 7.6, "tier": "mid", "basis": "4 matching Q&A questions, best 6.7"}, {"module": 12, "title": "Base rate vs description information", "a": {"term": "Base rate", "definition": "The background prevalence of categories, such as 70 lawyers and 30 engineers, or about 2.2 million farms and 120,000 libraries."}, "b": {"term": "Description information", "definition": "Personal characteristics that resemble a category, such as Jack's hobbies or Robert's glasses and quiet speech."}, "diff": "People use the base rate correctly when it is all they have, but disregard it once a description is given. That is base-rate neglect, where similarity displaces the prevalence of the categories.", "example": "With only the 70/30 split people say 30 in 100. After Jack is described as careful and enjoying mathematical puzzles, they call him an engineer.", "watch": "The base rate favors farmer for Robert even though he fits the librarian description.", "score": 6.5, "tier": "low", "basis": "1 matching Q&A question, best 6.5"}, {"module": 12, "title": "Conjunction rule vs representativeness", "a": {"term": "Conjunction rule", "definition": "Two things together can never be more probable than either alone, because every case where both are true is also a case where each is true."}, "b": {"term": "Representativeness", "definition": "Judging by how well a description fits a typical case, so a more detailed story that fits the person better feels more probable."}, "diff": "One is a rule about nested sets and the other is a shortcut by resemblance. They conflict when the combined description fits better than its single part. About 82 percent chose that Linda is a bank teller and active in the feminist movement over bank teller alone, but feminist bank tellers are a subset of bank tellers.", "example": "Linda is single, outspoken, bright, trained in philosophy and active in antinuclear demonstrations.", "watch": "More detail can make a story fit better but never makes it more probable.", "score": 7.6, "tier": "mid", "basis": "1 matching Q&A question, best 7.6"}, {"module": 12, "title": "Number of winners vs probability of winning", "a": {"term": "Attending to the number of favorable items", "definition": "Seven red beans looks like more chances than one red bean."}, "b": {"term": "Using the probability", "definition": "Seven in 100 is 7 percent and one in 10 is 10 percent, so the bowl with fewer red beans is better."}, "diff": "A larger number of favorable items draws attention away from the denominator, the total number of possible draws. The decision then depends on considerations other than the actual probabilities of winning.", "example": "In the jellybean problem a participant earns one dollar for each red bean drawn, and most participants chose the 7-out-of-100 bowl over the 1-out-of-10 bowl.", "watch": "Always compare proportions, not counts.", "score": 7.5, "tier": "mid", "basis": "1 matching Q&A question, best 7.5"}, {"module": 12, "title": "Small sample vs large sample", "a": {"term": "Larger hospital", "definition": "About 45 births a day, so its daily proportion of boys is more stable."}, "b": {"term": "Smaller hospital", "definition": "About 15 births a day, so extreme proportions are more likely."}, "diff": "The correct answer is the smaller hospital for more days with over 60 percent boys. The most common response, chosen by 56 percent, was about the same. The law of large numbers says larger random samples become more representative, and people wrongly expect small samples to be representative too.", "example": "Half of all babies are boys, but a single day's 15 births swing more than 45 births.", "watch": "Do not confuse the absolute number of boys with how often an extreme proportion occurs.", "score": 6.8, "tier": "low", "basis": "1 matching Q&A question, best 6.8"}, {"module": 12, "title": "Confirmation bias vs myside bias", "a": {"term": "Confirmation bias", "definition": "Seeking information that fits a hypothesis and overlooking what argues against it."}, "b": {"term": "Myside bias", "definition": "Generating and evaluating evidence, and testing hypotheses, in ways biased toward one's own opinions and attitudes."}, "diff": "Myside bias is one form of confirmation bias, tied to one's own opinions. In Lord and colleagues (1979), people for and against capital punishment read the same article and each side interpreted it as favoring their own position.", "example": "The 2, 4, 6 task shows confirmation bias. The capital punishment article shows myside bias.", "watch": "Myside bias is a form of confirmation bias, not a different bias.", "score": 9.1, "tier": "high", "basis": "1 matching Q&A question, best 9.1"}, {"module": 12, "title": "Testing what fits vs trying to disconfirm (2, 4, 6)", "a": {"term": "Positive testing", "definition": "Writing sets that fit the hypothesis, such as increasing by two, which keeps returning yes."}, "b": {"term": "Disconfirming", "definition": "Testing the boundaries of the belief to find where it breaks."}, "diff": "The most common hypothesis is increasing intervals of two, but the actual rule is any three numbers in increasing order. Only trying to disconfirm reveals that the narrow belief is wrong.", "example": "Participants write their own sets and get feedback only on whether each fits.", "watch": "Repeated yes feedback does not confirm a rule that is too narrow.", "score": 9.1, "tier": "high", "basis": "1 matching Q&A question, best 9.1"}, {"module": 12, "title": "Taboo tradeoff vs tragic tradeoff", "a": {"term": "Taboo tradeoff", "definition": "Mixes sacred and secular domains, such as a child's life against money. It provokes moral outrage."}, "b": {"term": "Tragic tradeoff", "definition": "Compares two sacred values with each other. People are less morally outraged."}, "diff": "The Sacred Value Protection Model (Tetlock, Kristel, Elson, Green and Lerner, 2000) says sacred values are compartmentalized from secular ones. Ask whether the competing item is a secular benefit (taboo) or another sacred value (tragic).", "example": "Johnny's liver costing one million dollars (taboo) versus two children and one available liver (tragic).", "watch": "A tragic tradeoff still involves a hard choice, but it does not threaten the sacred-secular boundary.", "score": 10.0, "tier": "high", "basis": "2 matching Q&A questions, best 9.7"}, {"module": 12, "title": "Outrage by tradeoff type and decision (Tetlock and colleagues, 2000)", "a": {"term": "Taboo tradeoff", "definition": "A sacred value (Johnny's life) is weighed against a secular benefit (one million dollars). Not saving Johnny drew much greater outrage than saving him, and spending the money on other uses instead of the child received the strongest negative response."}, "b": {"term": "Tragic tradeoff", "definition": "Two sacred values compete (two children, one available liver). Outrage was similar whether Johnny was saved or not, because either choice leaves a sacred concern unmet."}, "diff": "How outraged people are depends on both the type of value conflict and the decision made within it, and that interaction is the finding.", "example": "Tetlock and colleagues (2000) rated moral outrage for each combination of tradeoff type and decision.", "watch": "Do not say outrage depends only on the decision. It depends on the type of conflict as well.", "score": 10.0, "tier": "high", "basis": "2 matching Q&A questions, best 9.7"}, {"module": 12, "title": "Moral absolutists vs non-absolutists", "a": {"term": "Moral absolutists", "definition": "Treat the issue as a sacred value and reject compromise regardless of benefit."}, "b": {"term": "Non-absolutists", "definition": "Have strong preferences against compromise but do not treat the issue as sacred."}, "diff": "Ask whether benefits can enter the decision at all, not how much the person cares. For absolutists, adding money increased anger, disgust and support for violence, while for non-absolutists it reduced them.", "example": "Ginges, Atran, Medin and Shikaki (2007) studied 601 Israeli settlers, 535 Palestinian refugees and 719 Palestinian students.", "watch": "Absolutists are not just people who feel strongly. Their issue is sacred.", "score": 8.5, "tier": "mid", "basis": "1 matching Q&A question, best 8.5"}, {"module": 12, "title": "Money vs symbolic recognition", "a": {"term": "Material incentive (Taboo+)", "definition": "Money added to the deal, such as one billion dollars a year for ten years."}, "b": {"term": "Symbolic recognition", "definition": "Israeli recognition of the historic and legitimate right of Palestinians to their own state and an apology for wrongs done."}, "diff": "Money changes the economic benefit, and symbolic terms address the status of a group's claim. In Ginges, Atran, Medin and Shikaki (2007), money raised absolutists' anger, and the symbolic offer was associated with lower anger and lower support for violence.", "example": "Ginges, Atran, Medin and Shikaki (2007) added to the deal either one billion dollars a year for ten years or the recognition and apology.", "watch": "Material benefit and symbolic reciprocity are different.", "score": 8.8, "tier": "mid", "basis": "2 matching Q&A questions, best 8.5"}, {"module": 12, "title": "Incentive (Taboo+) vs disincentive (Taboo−)", "a": {"term": "Incentive", "definition": "A benefit offered for agreeing, such as 40 billion dollars from the United Nations."}, "b": {"term": "Disincentive", "definition": "A cost imposed for refusing, such as the threat of additional sanctions."}, "diff": "Incentives change the benefit of accepting, and disincentives change the cost of refusing. In the study by Dehghani and colleagues (2009, 2010), participants with a sacred value showed lower approval for energy with both the incentive and the sanction than with the baseline.", "example": "Dehghani and colleagues (2009, 2010) asked Iranian participants about a deal to give up their nuclear program, with or without an incentive or a sanction.", "watch": "For a sacred commitment, improving the material balance does not improve acceptability.", "score": 10.1, "tier": "high", "basis": "2 matching Q&A questions, best 9.8"}, {"module": 12, "title": "Participants with vs without a sacred value (Dehghani)", "a": {"term": "With a sacred value", "definition": "Said giving up the program should not be done no matter the consequences. About 14 percent for energy and 13 percent for weapons."}, "b": {"term": "Without a sacred value", "definition": "Had much higher approval and lower anger, with little variation across conditions."}, "diff": "For energy, anticipated anger was highest with the incentive and elevated with sanctions for those holding a sacred value. For participants without a sacred value, the deals barely mattered.", "example": "Dehghani, Atran and colleagues (2010) and Dehghani, Iliev and colleagues (2009) used a measure based on Baron and Spranca (1997).", "watch": "Only a small share of participants held the value as sacred, but they responded differently.", "score": 10.1, "tier": "high", "basis": "2 matching Q&A questions, best 9.8"}, {"module": 12, "title": "Net lives saved vs reluctance to cause a loss", "a": {"term": "Net-count reasoning", "definition": "Choosing the option that saves more overall. Rerouting the convoy saves 1,000 at a second camp and costs 100 at the first, a net of 900."}, "b": {"term": "Reluctance to cause a loss", "definition": "Resisting an action that makes others die even when more are saved elsewhere. In Ritov and Baron (1999), 63 percent did not choose to reroute."}, "diff": "Counting treats the lives lost by acting and the lives lost by not acting the same, but many people do not, and some would keep the original route even if only one person at the first camp would die. The better net count did not decide the choice.", "example": "In the convoy dilemma, food trucks are traveling to a refugee camp during a famine.", "watch": "The better net count did not decide the choice.", "score": 10.7, "tier": "high", "basis": "1 matching Q&A question, best 10.7"}, {"module": 12, "title": "Expected utility theory vs real choices", "a": {"term": "Expected utility theory", "definition": "Assumes rational people with all relevant information choose the option with the highest expected utility, which combines how valuable each outcome is with its chance. The monetary version uses the highest expected payoff."}, "b": {"term": "Real choices", "definition": "People find value in things other than money, and many decisions do not maximize the probability of the best outcome."}, "diff": "The theory gives a procedure for the best choice, but people are not utility-maximization machines, so it describes what a maximizer would do and not what people do.", "example": "Casino gambling: people choose it despite knowing the odds are strongly against them.", "watch": "Utility is how desirable an outcome is to the person, which is not the same as money.", "score": 3.8, "tier": "low", "basis": "1 matching Q&A question, best 3.8"}, {"module": 13, "title": "Valid vs true", "a": {"term": "Valid", "definition": "The conclusion follows logically from the premises. It depends on the form of the reasoning."}, "b": {"term": "True", "definition": "The statements match the world."}, "diff": "Ask two separate questions: does it follow, and are the statements correct. A valid syllogism with a false premise can have a false conclusion, and an invalid one can have statements that all seem reasonable.", "example": "All birds are animals, all animals have four legs, therefore all birds have four legs is valid, but its conclusion is false because premise 2 is false.", "watch": "Validity and truth can come apart in both directions: a valid argument can have a false conclusion, and an invalid one can have a true conclusion.", "score": 8.5, "tier": "mid", "basis": "4 matching Q&A questions, best 7.6"}, {"module": 13, "title": "Modus ponens vs modus tollens", "a": {"term": "Modus ponens", "definition": "If p then q; p; therefore q. Valid, and 97 percent judged it correctly."}, "b": {"term": "Modus tollens", "definition": "If p then q; not q; therefore not p. Valid, but only 60 percent judged it correctly."}, "diff": "Ponens affirms p and gets q. Tollens denies q and gets not p. Both are valid, but tollens feels harder.", "example": "If I study I'll get a good grade; I didn't get a good grade; therefore I didn't study.", "watch": "Both valid forms were judged correctly more often than both invalid ones.", "score": 7.9, "tier": "mid", "basis": "2 matching Q&A questions, best 7.6"}, {"module": 13, "title": "Modus tollens vs syllogism 3", "a": {"term": "Modus tollens", "definition": "From if p then q, plus not q, you may conclude not p. This form is valid."}, "b": {"term": "Syllogism 3", "definition": "From if p then q, plus q, you may not conclude p. This form is not valid, and only 40 percent judged it correctly."}, "diff": "Valid forms move from p to q or from not q to not p. Going from q back to p is not valid because there may be other ways to get q.", "example": "If I live in Tucson I live in Arizona; I live in Arizona; therefore I live in Tucson does not follow.", "watch": "The first premise says what follows from being in Tucson, not that Tucson is the only way to be in Arizona.", "score": 7.9, "tier": "mid", "basis": "2 matching Q&A questions, best 7.6"}, {"module": 13, "title": "Syllogism 3 vs syllogism 4", "a": {"term": "Syllogism 3", "definition": "If p then q; q; therefore p. Not valid."}, "b": {"term": "Syllogism 4", "definition": "If p then q; not p; therefore not q. Not valid."}, "diff": "Both are invalid, and 40 percent judged each correctly. In 3 the second premise is q, and in 4 it is not p. In 4, the first premise says nothing about what happens when someone does not study.", "example": "If I study I'll get a good grade; I did not study; so I did not get a good grade does not follow, because a good grade could come another way.", "watch": "Do not confuse them with the valid forms of the same premises.", "score": 7.9, "tier": "mid", "basis": "2 matching Q&A questions, best 7.6"}, {"module": 13, "title": "Inductive vs deductive reasoning", "a": {"term": "Inductive reasoning", "definition": "Reasoning from observations to conclusions that are probably but not definitely true."}, "b": {"term": "Deductive reasoning", "definition": "Determining whether a conclusion logically follows from the premises."}, "diff": "The strength of an inductive argument depends on the representativeness, number and quality of the observations. Many white swans support an expectation, and one clearly observed black swan contradicts it. Deduction asks whether the conclusion follows, not whether it is probable.", "example": "Seeing many white swans and expecting the next to be white is inductive. Checking whether a conclusion follows from two premises is deductive.", "watch": "Induction yields probable conclusions and deduction yields valid or invalid ones.", "score": 3.6, "tier": "low", "basis": "1 matching Q&A question, best 3.6"}, {"module": 13, "title": "Abstract vs concrete Wason problem", "a": {"term": "Abstract version", "definition": "Cards E, K, 4, 7 with the rule vowel then even number. The correct cards are E and 7. 46 percent chose the 4 and only 7 percent chose the 7."}, "b": {"term": "Concrete version", "definition": "The rule is 'If drinking beer, then 21 years old', with cards Beer, Soda, 16 years old and 21 years old. The correct cards are beer and 16 years old, and 73 percent answered correctly."}, "diff": "It is the same if p then q form. Concrete, familiar content calls up a permission schema. The falsification principle says to look for situations that falsify the rule.", "example": "Someone drinking beer while under 21 is the only case that breaks the rule.", "watch": "Context matters, but familiarity alone is not always the reason.", "score": 8.1, "tier": "mid", "basis": "2 matching Q&A questions, best 7.8"}, {"module": 13, "title": "Permission schema vs plain familiarity", "a": {"term": "Permission schema", "definition": "Stored knowledge that if a condition is satisfied, an action may be carried out, for example that being 21 permits drinking beer. It leads you to check for anyone doing the action without the condition."}, "b": {"term": "Plain familiarity", "definition": "Simply having experience with the content. By itself it does not always improve reasoning."}, "diff": "The improvement does not come from familiarity alone. A permission rule is easier to reason about than an abstract rule about letters and numbers.", "example": "Being 21 is the condition and drinking beer is what can then be carried out.", "watch": "The setting helps when it calls up a permission schema, and familiarity alone is not the reason.", "score": 6.4, "tier": "low", "basis": "1 matching Q&A question, best 6.4"}, {"module": 13, "title": "Gain frame vs loss frame", "a": {"term": "Gain frame", "definition": "Outcomes are described as people saved. Program A saves 200 for certain, while Program B has a 1/3 chance that all 600 are saved and a 2/3 chance that none are. 72 percent chose the sure A, a risk-averse choice."}, "b": {"term": "Loss frame", "definition": "The same outcomes are described as people who die. Program C means 400 die for certain, while Program D has a 1/3 chance that no one dies and a 2/3 chance that 600 die. 78 percent chose the gamble D, a risk-taking choice."}, "diff": "Program A is the same outcome as C, and B is the same gamble as D, so only the wording changed (Tversky and Kahneman, 1981). In the gain frame people avoid the uncertain option, and in the loss frame they accept uncertainty in the hope of avoiding a certain loss.", "example": "600 people are expected to die, and the choice is between a sure option and a gamble.", "watch": "Same facts, different wording, opposite choice.", "score": 10.1, "tier": "high", "basis": "3 matching Q&A questions, best 9.5"}, {"module": 13, "title": "Opt-in vs opt-out", "a": {"term": "Opt-in", "definition": "You must take a step to be an organ donor. Consent is under 28 percent."}, "b": {"term": "Opt-out", "definition": "You are a donor unless you request otherwise. Consent is over 99 percent."}, "diff": "Look at what doing nothing gives you. The status quo bias is the tendency to do nothing when faced with a difficult decision, so the default decides the result.", "example": "Doing nothing leaves you a non-donor under opt-in and a donor under opt-out.", "watch": "The rates differ because of the default, not the underlying attitude.", "score": 7.7, "tier": "mid", "basis": "1 matching Q&A question, best 7.7"}, {"module": 13, "title": "Expected emotions vs incidental emotions", "a": {"term": "Expected emotions", "definition": "Emotions people predict they will feel about an outcome."}, "b": {"term": "Incidental emotions", "definition": "Emotions not specifically related to the decision, from disposition, recent experience or surroundings."}, "diff": "Expected emotions are predictions about the outcome itself. Incidental emotions come from something unrelated yet still change the decision.", "example": "Kermer and colleagues (2006) studied predicted feelings about a coin flip. Lerner and colleagues (2004) induced mood with a film clip.", "watch": "A person's general disposition counts as an incidental source, so it can change a decision even when it has nothing to do with the choice.", "score": 10.2, "tier": "high", "basis": "2 matching Q&A questions, best 9.9"}, {"module": 13, "title": "Predicted vs actual feelings (Kermer, 2006)", "a": {"term": "Predicted feelings", "definition": "Participants expected losing $3 to lower happiness about 4 points and winning $5 to raise it about 2."}, "b": {"term": "Actual feelings", "definition": "The actual drop from losing was about 1 point and the rise from winning about 1.2."}, "diff": "People overestimate the negative feeling because they do not consider the coping mechanisms that soften a loss. That feeds risk aversion.", "example": "Kermer and colleagues (2006) gave participants $5 and a coin flip to win $5 more or lose $3.", "watch": "People believe a loss will have a greater impact than a gain of the same size.", "score": 9.5, "tier": "high", "basis": "1 matching Q&A question, best 9.5"}, {"module": 13, "title": "Sadness vs disgust: buying and selling prices (Lerner, 2004)", "a": {"term": "Sadness", "definition": "Lowered the selling price to about $3.00 but raised the buying price to about $4.50."}, "b": {"term": "Disgust", "definition": "Lowered both prices: selling about $2.70 versus $4.50 neutral, and buying about $3.00 versus $3.50 neutral."}, "diff": "The clips were unrelated to the choice, so these were incidental emotions, and they changed how much the same object seemed worth.", "example": "A sad clip of a person dying, a disgust clip of a dirty toilet, or a neutral clip of fish at the Great Barrier Reef, then prices for highlighters.", "watch": "Do not group the two emotions together, because they differ on the buying price.", "score": 9.9, "tier": "high", "basis": "1 matching Q&A question, best 9.9"}, {"module": 13, "title": "Cloudy vs sunny days (Simonsohn, 2007, 2009)", "a": {"term": "Cloudy days", "definition": "Applicants' academic attributes were weighted more heavily, and prospective students were more likely to enroll."}, "b": {"term": "Sunny days", "definition": "Academic attributes were weighted less heavily."}, "diff": "The weather is unrelated to the applicants or the school but still changed the decision. Incidental emotions include the surroundings, like the weather.", "example": "Simonsohn (2007) analyzed admissions decisions. Simonsohn (2009) found that visitors to a highly rated university were more likely to enroll if they came on a cloudy day.", "watch": "These are not decisions about the weather.", "score": 9.5, "tier": "high", "basis": "1 matching Q&A question, best 9.5"}, {"module": 13, "title": "Human vs computer partner (Sanfey, 2003)", "a": {"term": "Human partner", "definition": "An $8 and $2 offer was accepted about 53 percent of the time, and $9 and $1 about 37 percent."}, "b": {"term": "Computer partner", "definition": "The same offers were accepted about 85 percent and 68 percent."}, "diff": "Participants became angry at unfair offers, and they were less angry with an unfair computer. Fair offers were accepted almost every time for both.", "example": "Sanfey and colleagues (2003) had participants play 20 games, 10 with each partner type.", "watch": "The offers were identical. Only the partner changed.", "score": 8.9, "tier": "mid", "basis": "2 matching Q&A questions, best 8.6"}, {"module": 13, "title": "Rational responder vs actual responder", "a": {"term": "Rational responder", "definition": "According to utility theory, accept any offer, because even $1 is worth more than nothing."}, "b": {"term": "Actual responders", "definition": "Often rejected low offers, and participants with more right anterior insula activation rejected more, even though rejecting meant getting nothing."}, "diff": "Emotion is important in decision making, and it can lead people to give up money. In Sanfey and colleagues (2003), fair offers of $5 and $5 and $7 and $3 were accepted almost every time, while lower offers were often rejected. Neuroeconomics combines psychology, neuroscience and economics to study this.", "example": "The proposer gets $10 and offers the responder a split. If the responder rejects, neither receives anything.", "watch": "Rejecting is irrational by utility theory, yet common.", "score": 6.8, "tier": "low", "basis": "2 matching Q&A questions, best 6.5"}, {"module": 14, "title": "Decay vs interference as read from the Brown-Peterson task", "a": {"term": "Decay account", "definition": "Peterson and Peterson (1959) concluded that information fades from short-term memory over time unless it is rehearsed, because counting backward is so unlike remembering letters that it should not interfere with them."}, "b": {"term": "Interference account", "definition": "Keppel and Underwood (1962) offered the alternative that forgetting comes from other material getting in the way, as when letters from earlier trials compete with the set being tested."}, "diff": "Both accounts explain the same result, recall that gets worse the longer the counting lasts, but they predict different things. Decay depends only on time passing, so the trial history should not matter. Interference depends on what else is in memory, so recall at the same delay should be worse when more earlier sets have piled up, which is the pattern in the trial-by-trial data.", "example": "Peterson and Peterson (1959) read the drop in recall across longer delays as decay, while the trial-by-trial pattern is what points to proactive interference.", "watch": "Say who concluded what: the original authors chose decay, and the interference reading came from the later account.", "score": 9.5, "tier": "high", "basis": "extends the Brown-Peterson topic (Q&A 9.5)"}, {"module": 14, "title": "Heard lists vs read lists (modality effect)", "a": {"term": "Heard lists", "definition": "When items are heard, memory for the last items in the list is better. The advantage also appears for lip-read or mouthed lists."}, "b": {"term": "Read lists", "definition": "When items are only read silently, the memory advantage for the last items is smaller."}, "diff": "Neath and Surprenant (2003) tie the effect to extra information that comes with hearing, namely how the list sounded. The finding shaped ideas about sensory memory, because the end-of-list advantage seems to rely on a brief trace of the sound.", "example": "A list spoken aloud is remembered better at its end than the same list read on a screen.", "watch": "The effect concerns the last items of the list, not the whole list.", "score": 5.5, "tier": "low", "basis": "extends the echo and phonological loop topics (Q&A 3.6 to 9.5)"}, {"module": 14, "title": "Sound code vs look code (Conrad, 1964; Murray, 1968)", "a": {"term": "Phonological code", "definition": "A speech-based form of the items. If the items are held this way, sound-alike items are confused with one another."}, "b": {"term": "Visual code", "definition": "A memory of how the items look. If the items were held this way, look-alike items would be confused instead."}, "diff": "Conrad (1964) and Murray (1968) found that sound-alike lists were recalled worse, even when they were read silently. When articulatory suppression was applied to visually presented lists, the sound-alike cost disappeared, which shows people had been turning what they saw into a sound code.", "example": "The letters E and F look alike, but it was similar-sounding letters that were recalled worse.", "watch": "What matters is the code used to hold the items, not the format in which they arrived.", "score": 8.6, "tier": "mid", "basis": "extends Conrad (1964) (Q&A 8.6)"}, {"module": 14, "title": "Phonological similarity vs neighborhood size", "a": {"term": "Phonological similarity effect", "definition": "Items that sound alike are recalled worse because their sound codes overlap and get confused."}, "b": {"term": "Neighborhood size effect", "definition": "Words that have many similar-sounding neighbors in the language are recalled better, because long-term word knowledge supports the short-term trace."}, "diff": "One effect shows sound overlap hurting recall within the list, and the other shows what you already know about words helping recall. Roodenrys and colleagues (2002) found that large-neighborhood words were recalled better in short-term memory tasks, so memory span is not a pure measure of short-term capacity.", "example": "Cat is a large-neighborhood word and hippopotamus a small-neighborhood word, and Roodenrys and colleagues (2002) found large-neighborhood words are recalled better.", "watch": "Do not treat neighborhood size as another kind of sound confusion. It is a long-term memory benefit.", "score": 6.5, "tier": "low", "basis": "extends the phonological loop topic (Q&A 4.0 to 9.5)"}, {"module": 14, "title": "Framing effect vs default effect", "a": {"term": "Framing effect", "definition": "Choices change with the wording or context of equivalent options. Gain wording leads people to choose the sure option, and loss wording leads them to choose the gamble."}, "b": {"term": "Default effect", "definition": "People tend to choose the option that is already preselected, whatever the wording."}, "diff": "Framing is about how the options are described, and the default is about which option is already chosen. Giuliani and colleagues (2023) found a risky default raised risk taking, a sure default did not raise risk aversion, and the framing and default effects were additive.", "example": "In Giuliani and colleagues (2023), a risky default raised risk taking on top of the framing effect.", "watch": "People who rated the default as most rational followed it most, but that question came after the choice, so it does not show why they chose it.", "score": 8.0, "tier": "mid", "basis": "extends the framing effect (Q&A 9.2) and opt-in vs opt-out (7.7)"}, {"module": 14, "title": "Unconscious attribute substitution vs error sensitivity", "a": {"term": "Unconscious attribute substitution", "definition": "Kahneman and Frederick (2002) explain the error as answering an easier question in place of the one asked, for example by overlooking the words 'more than'."}, "b": {"term": "Error sensitivity", "definition": "Hoover and Healy (2019) prefer this term, because substitution cannot be confirmed as the cause of the error."}, "diff": "Substitution names a cause for the wrong answer, while error sensitivity stays closer to what was observed. Hoover and Healy (2019) found that wrong reasoners mostly remembered 'more than', so the phrase was not simply overlooked, which counts against the idea that it was dropped.", "example": "In the bat-and-ball problem (Frederick, 2005), Hoover and Healy (2019) checked what wrong reasoners remembered about the wording.", "watch": "Do not say the study proved substitution. It showed the cause cannot be confirmed.", "score": 6.0, "tier": "low", "basis": "article on heuristic errors, extends the Q&A heuristic topics (4.4 to 6.5)"}, {"module": 14, "title": "Reward system vs cognitive-control system", "a": {"term": "Reward system", "definition": "The ventral striatum and orbitofrontal cortex. Peers watching can make these regions more active."}, "b": {"term": "Cognitive-control system", "definition": "The lateral prefrontal cortex, which matures slowly and supports controlling impulses."}, "diff": "In Chein and colleagues (2011), adolescents watched by friends took more risks and showed more reward-region activity, while cognitive-control regions did not change with peers. Albert, Chein and Steinberg (2013) read this as the peer effect working mainly through reward circuitry and not through weaker reasoning.", "example": "An adolescent driving riskily when friends watch is explained by a more active reward system, not a less active control system.", "watch": "Peers raised reward activity, but they did not lower cognitive control.", "score": 5.5, "tier": "low", "basis": "neuroscience of risky decisions, extends Sanfey (2003) (Q&A 8.6)"}, {"module": 14, "title": "Offloading vs rehearsal", "a": {"term": "Offloading", "definition": "Using actions such as writing things down to reduce the mental load on memory."}, "b": {"term": "Rehearsal", "definition": "Repeating information mentally so that it is not lost."}, "diff": "Offloading puts the load outside the head, and rehearsal keeps it inside. Morrison and Richmond (2020) found that offloading improved memory, especially at high loads, and that people offloaded more as the load grew, while memory ability did not predict who offloaded.", "example": "When Morrison and Richmond (2020) let people use pen and paper, memory improved most when the list was long.", "watch": "Offloading looks like a strategy used across abilities, not only by people with weak memory.", "score": 6.0, "tier": "low", "basis": "extends maintenance rehearsal (Q&A 4.5)"}, {"module": 14, "title": "Verbal vs spatial items under irrelevant speech", "a": {"term": "Verbal items", "definition": "Items that can be named and held in a speech-based code, such as pictured objects."}, "b": {"term": "Spatial items", "definition": "Items defined by where they are, such as dot locations."}, "diff": "Leist and colleagues (2022) found that ignored speech hurt serial recall of verbal items but not spatial items, in both children and adults. That fits interference with phonological codes better than accounts based on attention capture or changing-state speech.", "example": "Third graders and adults were hurt on the objects but not on the dot locations.", "watch": "The speech effect is specific to verbal material, so it does not show a general loss of attention.", "score": 7.0, "tier": "mid", "basis": "extends the loop vs sketchpad contrast (Q&A 9.5)"}, {"module": 14, "title": "Falsifying a rule vs confirming it (Wason and Shapiro, 1971)", "a": {"term": "Falsify", "definition": "Choosing the cases that could show the rule is broken."}, "b": {"term": "Confirm", "definition": "Choosing a case that can only agree with the rule and so cannot test it."}, "diff": "A card that cannot break the rule teaches nothing, however well it fits, because the rule says nothing about what is behind it. On the abstract rule Wason and Shapiro (1971) found most people picked a confirming card, while thematic rules were much easier because relevant experience helps people test them.", "example": "On the abstract rule most people added a confirming card to the correct one, instead of the card that could break the rule.", "watch": "A choice that agrees with the rule is not a test of it.", "score": 7.8, "tier": "mid", "basis": "extends the Wason problem (Q&A 7.8)"}, {"module": 14, "title": "Younger vs older children and functional fixedness", "a": {"term": "Older children", "definition": "German and Defeyter (2000) found children aged 6 and 7 were slower after seeing the box used as a container, so one shown use had locked the object in."}, "b": {"term": "Younger children", "definition": "German and Defeyter (2000) found the 5-year-olds were not slowed, and were even faster than the older children after seeing the box as a container."}, "diff": "The results suggest younger children have a more fluid idea of function, so one shown use did not lock the object in. This is immunity to functional fixedness in young children.", "example": "German and Defeyter (2000) first showed the children the box used as a container and then measured how fast they solved the problem.", "watch": "The finding is about speed after being shown a use, so it does not say young children never show fixedness.", "score": 6.5, "tier": "low", "basis": "extends functional fixedness and the candle problem (Q&A 6.5)"}, {"module": 14, "title": "Staying vs switching in the Monty Hall problem", "a": {"term": "Staying", "definition": "Keeping the first choice keeps only the chance that the first guess was right, which is the smaller share."}, "b": {"term": "Switching", "definition": "Switching wins the larger share, because the first guess was probably wrong and the revealed option removes a wrong one."}, "diff": "The first pick keeps its original chance, so the remaining chance moves to the one other option left. Many people think it makes no difference, which is the intuition the problem is used to show is mistaken.", "example": "After the first choice, a losing option is revealed, and switching then wins more often than staying.", "watch": "Do not reason that two options left means equal chances.", "score": 5.0, "tier": "low", "basis": "extends judgment and probability topics (Q&A 6.8 to 7.6)"}, {"module": 14, "title": "Percent correct vs the pattern of position errors", "a": {"term": "Percent correct", "definition": "Counts only how many items were placed in exactly the right position."}, "b": {"term": "Position error pattern", "definition": "Looks at where the wrong items went. Items were usually placed correctly, and errors were systematic, with the item landing in an adjacent position."}, "diff": "People keep approximate position information even when they miss the exact one. A percent-correct score hides this, because an item one place off counts as completely wrong.", "example": "An item placed one position away from its true spot is scored as an error but still shows partial knowledge of its position.", "watch": "Look at which errors were made, not only how many.", "score": 4.5, "tier": "low", "basis": "lab result with no direct Q&A link"}, {"module": 14, "title": "Self-report of imagery vs an imagery task (Shepard and Metzler, 1971)", "a": {"term": "Self-report of imagery", "definition": "Asking people to describe their mental images is unreliable, because you cannot tell whether the images or only the descriptions differ."}, "b": {"term": "An imagery task with a varied critical part", "definition": "Shepard and Metzler (1971) had people judge whether two block shapes were the same or mirror images when one was turned."}, "diff": "The larger the turn, the longer the response, at a constant rate. This suggests mental images are much like real images, because people mentally rotate them.", "example": "Response time rose at a constant rate as the turn between the two shapes grew.", "watch": "The evidence is the pattern of response times, not what people say they see.", "score": 9.0, "tier": "high", "basis": "repeats Shepard and Metzler (Q&A 9.5)"}, {"module": 13, "title": "Validity vs believability (belief bias and mental models)", "a": {"term": "Validity", "definition": "Asks whether the conclusion must follow if the premises are true. It depends on the form of the argument and not on what the words say."}, "b": {"term": "Believability", "definition": "Asks whether the conclusion sounds true given what you know. Belief bias is judging a syllogism valid because its conclusion is believable."}, "diff": "These are separate questions, and belief bias is answering the second when asked the first: 71 percent judged invalid syllogisms with believable conclusions as valid. The mental model approach (Johnson-Laird, 1999) is the safeguard. You build a model of the premises, form a tentative conclusion, then search for an exception where the premises hold but the conclusion fails, and the conclusion is valid only if no such model exists.", "example": "All of the students are tired, some tired people are irritable, so some of the students are irritable. It seems reasonable but is invalid.", "watch": "A believable conclusion does not make a syllogism valid, and an unbelievable one does not make it invalid.", "score": 7.0, "tier": "mid", "basis": "1 matching Q&A question, best 7.0"}, {"module": 6, "title": "Short-term memory vs long-term memory", "a": {"term": "Short-term memory", "definition": "Holds about five to seven items for roughly fifteen to twenty seconds and is easily disrupted by interruption and interference."}, "b": {"term": "Long-term memory", "definition": "Retains large amounts of information for years or even decades."}, "diff": "Rehearsal moves information from short-term toward long-term memory, and retrieval moves it back, so the flow goes both ways and not only toward storage. Short-term memory is the active window on the present, and long-term memory is the large body of knowledge stored outside current awareness.", "example": "You look up a phone number, repeat it to keep it in short-term memory, and later retrieve it from long-term memory back into short-term memory to dial it.", "watch": "Do not treat long-term memory as simply more of short-term memory. They differ in capacity and in duration.", "score": 8.9, "tier": "mid", "basis": "4 matching Q&A questions, best 8.0"}, {"module": 6, "title": "Declarative vs procedural memory", "a": {"term": "Declarative memory", "definition": "Long-term memory for events and knowledge, with two branches: episodic memory for events and semantic memory for facts."}, "b": {"term": "Procedural memory", "definition": "Long-term memory for skills."}, "diff": "The memory tree sorts long-term memory by function and not by how long things last. Declarative memory is what you can state, and procedural memory is what you can do.", "example": "Knowing what a bicycle is is declarative, and knowing how to ride one is procedural.", "watch": "Episodic and semantic memory are both inside declarative memory.", "score": 4.5, "tier": "low", "basis": "1 matching Q&A question, best 4.5"}, {"module": 6, "title": "Encoding, storage and retrieval failure", "a": {"term": "Encoding and storage", "definition": "Encoding converts information into a form that can be stored, and storage keeps it."}, "b": {"term": "Retrieval", "definition": "Bringing stored information back out when it is needed."}, "diff": "A failure to remember could come from a problem at any of the three operations, so forgetting on its own does not show which one failed. Memory is also an active system that can organize and even alter information, so it is not a recording kept unchanged.", "example": "Forgetting a familiar name could mean it was never encoded well, was lost from storage, or cannot be retrieved right now.", "watch": "Do not name the failed stage from the failure alone.", "score": 6.7, "tier": "low", "basis": "2 matching Q&A questions, best 6.4"}, {"module": 6, "title": "Simple vs complex objects in visual short-term memory", "a": {"term": "Simple objects", "definition": "Objects such as colored squares need little information to represent, so more of them can be held."}, "b": {"term": "Complex objects", "definition": "Objects such as polygons, shaded cubes or Chinese-character-like forms need more information to represent, so fewer can be held."}, "diff": "Alvarez and Cavanagh (2004) found that same-different performance depends on how complex the stimuli are, so capacity is constrained by the amount of information needed to represent the objects. A capacity for one category of stimulus is not a universal estimate for all visual objects.", "example": "Colored squares supported a higher estimated capacity than shaded cubes in the change-detection task.", "watch": "Do not count every object as an equally sized item.", "score": 8.8, "tier": "mid", "basis": "2 matching Q&A questions, best 8.5"}, {"module": 10, "title": "Triangle problem vs chain problem", "a": {"term": "Triangle problem", "definition": "Ten dots form an upward-pointing triangle, and you must move exactly three dots to make it point down, with seven staying in place."}, "b": {"term": "Chain problem", "definition": "Four short sections of chain must become one closed loop, where opening a link costs 2 cents, closing it costs 3 cents and the budget is 15 cents."}, "diff": "Both are insight problems used by Metcalfe and Wiebe (1987), and both are solved by a change in representation. In the triangle the top dot becomes a new bottom point, and in the chain one three-link section is opened into separate links that join the other three sections.", "example": "Metcalfe and Wiebe (1987) compared both with algebra and found warmth jumped late for them, from about 3 to 7.", "watch": "In the chain problem three open-and-close operations use the full 15 cents.", "score": 9.8, "tier": "high", "basis": "2 matching Q&A questions, best 9.5"}, {"module": 10, "title": "Problem vs knowing the goal", "a": {"term": "A problem", "definition": "A situation with a present state, a goal and an obstacle between them, where the solution is not immediately obvious."}, "b": {"term": "Stating the goal", "definition": "Being able to describe exactly what the finished situation looks like."}, "diff": "The difficulty is the route and not whether the goal has been stated. In the numbered-tile puzzle you can describe the goal arrangement exactly and still not know the sequence of moves that gets there.", "example": "The initial state is 8, empty, 6 over 5, 4, 7 over 2, 3, 1, and the goal is empty, 1, 2 over 3, 4, 5 over 6, 7, 8.", "watch": "A tile being on the board does not mean it is in its required position, because the whole arrangement defines the state.", "score": 1.4, "tier": "low", "basis": "1 matching Q&A question, best 1.4"}, {"module": 11, "title": "Russian marriage problem vs mutilated checkerboard", "a": {"term": "Russian marriage problem (source)", "definition": "There are 32 bachelors and 32 unmarried women. After two bachelors die, 30 men and 32 women remain and the question is whether 31 heterosexual marriages can be formed. The answer is no."}, "b": {"term": "Mutilated checkerboard (target)", "definition": "Removing two opposite corners leaves 62 squares, which matches the area of 31 dominoes, but the two removed squares are the same color so the covering is impossible."}, "diff": "Marriages correspond to dominoes, the two groups of people correspond to the two square colors, and removing two bachelors corresponds to removing two same-colored squares. The useful information transferred from the source is the relationship among the elements and not their identical appearance.", "example": "A valid marriage needs one member of each group, just as a domino needs one square of each color.", "watch": "Dividing 62 by two gives 31 pairs by total size but ignores which kinds each pair must contain.", "score": 7.0, "tier": "low", "basis": "2 matching Q&A questions, best 6.7"}, {"module": 11, "title": "Having an idea vs creative problem solving", "a": {"term": "Having an idea", "definition": "Generating a novel idea or new connection. Divergent thinking is open-ended and allows many potential solutions."}, "b": {"term": "Creative problem solving", "definition": "A fuller process that includes problem generation, formulation, solving with evaluation and planning, and solution implementation, usually after a lengthy period of trial and error."}, "diff": "Ideas are necessary, since without them the process stops, but generating them does not evaluate, plan or carry out a response.", "example": "Finding the problem, defining it and finding ideas come before evaluating and acting on them.", "watch": "Creativity is more than getting an idea.", "score": 4.7, "tier": "low", "basis": "1 matching Q&A question, best 4.7"}, {"module": 12, "title": "Easy to recall vs actually frequent (availability)", "a": {"term": "Easy to bring to mind", "definition": "Events or words that are distinctive, emotionally salient or retrieved easily, which makes them feel more numerous."}, "b": {"term": "Actually frequent", "definition": "How often the event or word really occurs."}, "diff": "About 70 percent say English has more words beginning with r than words with r as the third letter, but r-third words are about three times more common. A death from botulism can be front-page news while asthma deaths go virtually unnoticed, so people pick the less likely cause.", "example": "Retrieving words by first letter is easier, so those words feel more numerous.", "watch": "Memorability is not frequency.", "score": 6.7, "tier": "low", "basis": "1 matching Q&A question, best 6.7"}, {"module": 12, "title": "Illusory correlation vs a real association", "a": {"term": "Illusory correlation", "definition": "A relationship that appears to exist even though it does not exist or is much weaker than assumed."}, "b": {"term": "Real association", "definition": "A relationship that is actually present in the data."}, "diff": "Stereotypes direct attention to behaviors that fit the expected description, and remembering the matching instances makes the stereotype feel supported. Stereotype-consistent behaviors are easier to bring to mind, and their availability is mistaken for evidence that the behavior is strongly associated with the group.", "example": "A stereotype feels confirmed because the fitting instances were noticed and retained.", "watch": "The apparent evidence is shaped by what was noticed and remembered.", "score": 4.4, "tier": "low", "basis": "1 matching Q&A question, best 4.4"}, {"module": 12, "title": "Feared event vs actual risk (after September 11)", "a": {"term": "Emotional impact", "definition": "The fear produced by the attacks led to a decision based on how the event felt."}, "b": {"term": "Relative probability", "definition": "The probability of dying in a car accident is much greater than while flying."}, "diff": "After September 11, air travel decreased and driving increased. The reported number of Americans who died on the road while avoiding flying exceeded the total number of passengers killed on the four hijacked flights.", "example": "Avoiding the feared event increased exposure to a more likely danger.", "watch": "Emotional impact and probability are different bases for a decision.", "score": 1.4, "tier": "low", "basis": "1 matching Q&A question, best 1.4"}, {"module": 12, "title": "Decision vs judgment vs reasoning", "a": {"term": "Decision", "definition": "The process of choosing between alternatives."}, "b": {"term": "Judgment and reasoning", "definition": "Reasoning is the process of drawing conclusions, and decisions are based on the judgments people make."}, "diff": "Inductive reasoning, from observations to conclusions that are probably but not definitely true, is one of the primary mechanisms involved in making judgments.", "example": "In everyday life people use past experience to predict what will happen, especially in familiar situations.", "watch": "A decision is a choice, and a judgment is an estimate that feeds it.", "score": 3.6, "tier": "low", "basis": "1 matching Q&A question, best 3.6"}, {"module": 13, "title": "Context of a decision (cesarean case)", "a": {"term": "Seen alone", "definition": "Physicians read the hypothetical cesarean test case by itself as the control."}, "b": {"term": "Seen after other cases", "definition": "Physicians read the same case after four cases with serious complications, or after four fairly routine cases."}, "diff": "Significantly more doctors recommended cesarean after reading the non-serious cases first, so the cases just considered changed how the same patient was judged.", "example": "The identical patient was judged differently depending on the cases read before.", "watch": "Decisions depend on context and on how choices are presented.", "score": 7.7, "tier": "mid", "basis": "1 matching Q&A question, best 7.7"}, {"module": 13, "title": "Emotion as a help vs a hindrance in decisions", "a": {"term": "Emotion that helps", "definition": "People with damage to an area of the prefrontal cortex who have flattened emotions have impaired decision making, so emotion takes part in decisions."}, "b": {"term": "Emotion in excess", "definition": "Anxious people tend toward risk avoidance, and optimistic people ignore negative information, which in excess can lead to poor decisions."}, "diff": "Emotions take part in decision making and do not only get in its way. Whether they help depends on how they push the choice.", "example": "Passing up choices that could lead to large negative consequences is the anxious pattern.", "watch": "Emotion is not simply the opposite of good decision making.", "score": 4.5, "tier": "low", "basis": "1 matching Q&A question, best 4.5"}, {"module": 13, "title": "Categorical vs conditional syllogism", "a": {"term": "Categorical syllogism", "definition": "Describes the relation between two categories using all, no or some, such as All birds are animals, All animals eat food, therefore all birds eat food."}, "b": {"term": "Conditional syllogism", "definition": "Has a first premise of the form If p, then q, where p is the condition and q is what follows."}, "diff": "Both have two premises and a conclusion, and Aristotle introduced the syllogism. The conditional kind has four types that differ in the second premise, two valid and two not valid.", "example": "If I study I'll get a good grade is a conditional first premise.", "watch": "A syllogism can be invalid even when every statement seems reasonable.", "score": 7.0, "tier": "mid", "basis": "1 matching Q&A question, best 7.0"}];
